// Good Overloading: Logically similar behavior (printing/output)
void Display(int value);
void Display(double value, int precision);
void Display(const std::string& message);

// Anti-Pattern: Overloading unrelated operations
// Bad: 'Execute' means loading AND deleting
void LoadUser(int id);
void DeleteDirectory(const Path& p);

